<?php
declare(strict_types=1);
$id='CHAR(36) CHARACTER SET ascii COLLATE ascii_bin';$e=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
$sql=[
"INSERT INTO identity_permissions(code) VALUES ('support.ticket.assign')",
"INSERT INTO identity_role_permissions(role_id,permission) SELECT id,'support.ticket.assign' FROM identity_roles WHERE name IN ('Super Admin','Destek')",
"CREATE TABLE support_work_policies(id $id PRIMARY KEY,department_id $id NOT NULL,revision INT UNSIGNED NOT NULL,spec LONGTEXT NOT NULL CHECK(JSON_VALID(spec)),actor_id $id NOT NULL,session_id $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_work_policy(department_id,revision),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(actor_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
"CREATE TABLE support_work_heads(department_id $id PRIMARY KEY,policy_id $id NULL,version INT UNSIGNED NOT NULL DEFAULT 0,rr_cursor $id NULL,FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(policy_id) REFERENCES support_work_policies(id))$e",
"CREATE TABLE support_work_rosters(id $id PRIMARY KEY,department_id $id NOT NULL,user_id $id NOT NULL,revision INT UNSIGNED NOT NULL,spec LONGTEXT NOT NULL CHECK(JSON_VALID(spec)),actor_id $id NOT NULL,session_id $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_work_roster(department_id,user_id,revision),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(user_id) REFERENCES identity_users(id),FOREIGN KEY(actor_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
"CREATE TABLE support_work_roster_heads(department_id $id NOT NULL,user_id $id NOT NULL,roster_id $id NOT NULL,version INT UNSIGNED NOT NULL,PRIMARY KEY(department_id,user_id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(user_id) REFERENCES identity_users(id),FOREIGN KEY(roster_id) REFERENCES support_work_rosters(id))$e",
"CREATE TABLE support_work_tickets(ticket_id $id PRIMARY KEY,customer_id $id NOT NULL,department_id $id NOT NULL,policy_id $id NULL,cycle_id $id NULL,assignee_id $id NULL,manual_override BOOLEAN NOT NULL DEFAULT FALSE,assignment_version INT UNSIGNED NOT NULL DEFAULT 0,weight INT UNSIGNED NOT NULL DEFAULT 0,reason VARCHAR(40) NOT NULL DEFAULT 'UNCONFIGURED',checked_at DATETIME(6) NOT NULL DEFAULT '2000-01-01 00:00:00',version INT UNSIGNED NOT NULL DEFAULT 1,FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(policy_id) REFERENCES support_work_policies(id),FOREIGN KEY(assignee_id) REFERENCES identity_users(id),KEY ix_work_fair(checked_at,ticket_id),KEY ix_work_load(department_id,assignee_id))$e",
"CREATE TABLE support_sla_cycles(id $id PRIMARY KEY,ticket_id $id NOT NULL,customer_id $id NOT NULL,department_id $id NOT NULL,policy_id $id NOT NULL,source_event $id NOT NULL UNIQUE,opened_at DATETIME(6) NOT NULL,closed_at DATETIME(6) NULL,close_reason VARCHAR(32) NULL,FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(policy_id) REFERENCES support_work_policies(id))$e",
"ALTER TABLE support_work_tickets ADD FOREIGN KEY(cycle_id) REFERENCES support_sla_cycles(id)",
"CREATE TABLE support_sla_clocks(id $id PRIMARY KEY,cycle_id $id NOT NULL,metric VARCHAR(16) NOT NULL CHECK(metric IN ('FIRST','NEXT','RESOLUTION')),source_event $id NOT NULL,target_us BIGINT UNSIGNED NOT NULL,consumed_us BIGINT UNSIGNED NOT NULL DEFAULT 0,last_at DATETIME(6) NOT NULL,status VARCHAR(16) NOT NULL CHECK(status IN ('RUNNING','PAUSED','COMPLETED','CANCELLED')),deadline_at DATETIME(6) NULL,completed_at DATETIME(6) NULL,version INT UNSIGNED NOT NULL DEFAULT 1,UNIQUE KEY uq_sla_source(cycle_id,metric,source_event),FOREIGN KEY(cycle_id) REFERENCES support_sla_cycles(id),KEY ix_sla_active(cycle_id,status))$e",
"CREATE TABLE support_sla_history(id $id PRIMARY KEY,clock_id $id NOT NULL,source_event $id NOT NULL,kind VARCHAR(24) NOT NULL,snapshot LONGTEXT NOT NULL CHECK(JSON_VALID(snapshot)),observed_at DATETIME(6) NOT NULL,UNIQUE KEY uq_sla_history(clock_id,source_event,kind),FOREIGN KEY(clock_id) REFERENCES support_sla_clocks(id))$e",
"CREATE TABLE support_sla_alerts(id $id PRIMARY KEY,clock_id $id NOT NULL,level VARCHAR(8) NOT NULL CHECK(level IN ('RISK','BREACH')),consumed_us BIGINT UNSIGNED NOT NULL,target_us BIGINT UNSIGNED NOT NULL,observed_at DATETIME(6) NOT NULL,UNIQUE KEY uq_sla_alert(clock_id,level),FOREIGN KEY(clock_id) REFERENCES support_sla_clocks(id))$e",
"CREATE TABLE support_work_events(id $id PRIMARY KEY,ticket_id $id NULL,customer_id $id NULL,department_id $id NOT NULL,kind VARCHAR(40) NOT NULL,actor_id VARCHAR(64) CHARACTER SET ascii NOT NULL,target_user $id NULL,clock_id $id NULL,source_event $id NULL,ticket_version INT UNSIGNED NULL,details LONGTEXT NOT NULL CHECK(JSON_VALID(details)),trace_id $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(target_user) REFERENCES identity_users(id),FOREIGN KEY(clock_id) REFERENCES support_sla_clocks(id),KEY ix_work_event(ticket_id,created_at,id))$e",
"CREATE TABLE support_work_confirmations(id $id PRIMARY KEY,actor_id $id NOT NULL,session_id $id NOT NULL,identity_version INT UNSIGNED NOT NULL,action VARCHAR(32) NOT NULL,payload_hmac CHAR(64) NOT NULL,state_hmac CHAR(64) NOT NULL,expires_at DATETIME(6) NOT NULL,used_at DATETIME(6) NULL,FOREIGN KEY(actor_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
];
foreach(['support_work_policies','support_work_rosters','support_sla_history','support_sla_alerts','support_work_events'] as $t){foreach(['UPDATE','DELETE'] as $v){$suffix=strtolower($v);$sql[]="CREATE TRIGGER {$t}_no_{$suffix} BEFORE $v ON $t FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable support work history'";}}
$sql[]="CREATE TRIGGER support_cycle_identity BEFORE UPDATE ON support_sla_cycles FOR EACH ROW BEGIN IF NOT(OLD.id<=>NEW.id) OR NOT(OLD.ticket_id<=>NEW.ticket_id) OR NOT(OLD.customer_id<=>NEW.customer_id) OR NOT(OLD.department_id<=>NEW.department_id) OR NOT(OLD.policy_id<=>NEW.policy_id) OR NOT(OLD.source_event<=>NEW.source_event) OR NOT(OLD.opened_at<=>NEW.opened_at) OR OLD.closed_at IS NOT NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable SLA cycle snapshot'; END IF; END";
$sql[]="CREATE TRIGGER support_clock_identity BEFORE UPDATE ON support_sla_clocks FOR EACH ROW BEGIN IF NOT(OLD.id<=>NEW.id) OR NOT(OLD.cycle_id<=>NEW.cycle_id) OR NOT(OLD.metric<=>NEW.metric) OR NOT(OLD.source_event<=>NEW.source_event) OR NOT(OLD.target_us<=>NEW.target_us) OR NEW.consumed_us<OLD.consumed_us OR NEW.last_at<OLD.last_at OR OLD.status IN ('COMPLETED','CANCELLED') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable SLA clock identity or completed result'; END IF; END";
return $sql;
